mkitem!{# [doc = " `impl` implementation of struct/trait"] const BASE_IMPL : & [& str] = & [label_strs :: associated_item_def_ids , label_strs :: generics_of , label_strs :: impl_trait_header] ;}
mkitem!{# [doc = " DepNodes for exported mir bodies, which is relevant in \"executable\""] # [doc = " code, i.e., functions+methods"] const BASE_MIR : & [& str] = & [label_strs :: optimized_mir , label_strs :: promoted_mir] ;}
mkitem!{# [doc = " Struct, Enum and Union DepNodes"] # [doc = ""] # [doc = " Note that changing the type of a field does not change the type of the struct or enum, but"] # [doc = " adding/removing fields or changing a fields name or visibility does."] const BASE_STRUCT : & [& str] = & [label_strs :: generics_of , label_strs :: predicates_of , label_strs :: type_of] ;}
mkitem!{# [doc = " Trait definition `DepNode`s."] # [doc = " Extra `DepNode`s for functions and methods."] const EXTRA_ASSOCIATED : & [& str] = & [label_strs :: associated_item] ;}
mkitem!{const EXTRA_TRAIT : & [& str] = & [] ;}
mkitem!{const LABELS_CONST : & [& [& str]] = & [BASE_HIR , BASE_CONST] ;}
mkitem!{# [doc = " Constant/Typedef in an impl"] const LABELS_CONST_IN_IMPL : & [& [& str]] = & [BASE_HIR , BASE_CONST , EXTRA_ASSOCIATED] ;}
mkitem!{# [doc = " Trait-Const/Typedef DepNodes"] const LABELS_CONST_IN_TRAIT : & [& [& str]] = & [BASE_HIR , BASE_CONST , EXTRA_ASSOCIATED , EXTRA_TRAIT] ;}
mkitem!{# [doc = " Function `DepNode`s."] const LABELS_FN : & [& [& str]] = & [BASE_HIR , BASE_MIR , BASE_FN] ;}
mkitem!{# [doc = " Method `DepNode`s."] const LABELS_FN_IN_IMPL : & [& [& str]] = & [BASE_HIR , BASE_MIR , BASE_FN , EXTRA_ASSOCIATED] ;}
mkitem!{# [doc = " Trait method `DepNode`s."] const LABELS_FN_IN_TRAIT : & [& [& str]] = & [BASE_HIR , BASE_MIR , BASE_FN , EXTRA_ASSOCIATED , EXTRA_TRAIT] ;}
mkitem!{# [doc = " For generic cases like inline-assembly, modules, etc."] const LABELS_HIR_ONLY : & [& [& str]] = & [BASE_HIR] ;}
mkitem!{# [doc = " Impl `DepNode`s."] const LABELS_TRAIT : & [& [& str]] = & [BASE_HIR , & [label_strs :: associated_item_def_ids , label_strs :: predicates_of , label_strs :: generics_of] ,] ;}
mkitem!{# [doc = " Impl `DepNode`s."] const LABELS_IMPL : & [& [& str]] = & [BASE_HIR , BASE_IMPL] ;}
mkitem!{# [doc = " Abstract data type (struct, enum, union) `DepNode`s."] const LABELS_ADT : & [& [& str]] = & [BASE_HIR , BASE_STRUCT] ;}
mkitem!{type Labels = UnordSet < String > ;}
mkitem!{mkstruct!{# [doc = " Represents the requested configuration by rustc_clean/dirty"] struct Assertion { clean : Labels , dirty : Labels , loaded_from_disk : Labels , }}}

macro_rules! check_dirty_clean_annotations_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function check_dirty_clean_annotations in module {}", module_path!());
    };
}

mkfn!{
    check_dirty_clean_annotations_introspect!();
    pub (crate) fn check_dirty_clean_annotations (tcx : TyCtxt < '_ >) { if ! tcx . sess . opts . unstable_opts . query_dep_graph { return ; } if ! tcx . features () . rustc_attrs () { return ; } tcx . dep_graph . with_ignore (| | { let mut dirty_clean_visitor = DirtyCleanVisitor { tcx , checked_attrs : Default :: default () } ; let crate_items = tcx . hir_crate_items (()) ; for id in crate_items . free_items () { dirty_clean_visitor . check_item (id . owner_id . def_id) ; } for id in crate_items . trait_items () { dirty_clean_visitor . check_item (id . owner_id . def_id) ; } for id in crate_items . impl_items () { dirty_clean_visitor . check_item (id . owner_id . def_id) ; } for id in crate_items . foreign_items () { dirty_clean_visitor . check_item (id . owner_id . def_id) ; } let mut all_attrs = FindAllAttrs { tcx , found_attrs : vec ! [] } ; tcx . hir_walk_attributes (& mut all_attrs) ; all_attrs . report_unchecked_attrs (dirty_clean_visitor . checked_attrs) ; }) }
}
mkitem!{mkstruct!{struct DirtyCleanVisitor < 'tcx > { tcx : TyCtxt < 'tcx > , checked_attrs : FxHashSet < ast :: AttrId > , }}}
mkitem!{mkimpl!{impl < 'tcx > DirtyCleanVisitor < 'tcx > { # [doc = " Possibly \"deserialize\" the attribute into a clean/dirty assertion"] fn assertion_maybe (& mut self , item_id : LocalDefId , attr : & Attribute) -> Option < Assertion > { assert ! (attr . has_name (sym :: rustc_clean)) ; if ! check_config (self . tcx , attr) { return None ; } let assertion = self . assertion_auto (item_id , attr) ; Some (assertion) } # [doc = " Gets the \"auto\" assertion on pre-validated attr, along with the `except` labels."] fn assertion_auto (& mut self , item_id : LocalDefId , attr : & Attribute) -> Assertion { let (name , mut auto) = self . auto_labels (item_id , attr) ; let except = self . except (attr) ; let loaded_from_disk = self . loaded_from_disk (attr) ; for e in except . items () . into_sorted_stable_ord () { if ! auto . remove (e) { self . tcx . dcx () . emit_fatal (errors :: AssertionAuto { span : attr . span () , name , e }) ; } } Assertion { clean : auto , dirty : except , loaded_from_disk } } # [doc = " `loaded_from_disk=` attribute value"] fn loaded_from_disk (& self , attr : & Attribute) -> Labels { for item in attr . meta_item_list () . unwrap_or_else (ThinVec :: new) { if item . has_name (LOADED_FROM_DISK) { let value = expect_associated_value (self . tcx , & item) ; return self . resolve_labels (& item , value) ; } } Labels :: default () } # [doc = " `except=` attribute value"] fn except (& self , attr : & Attribute) -> Labels { for item in attr . meta_item_list () . unwrap_or_else (ThinVec :: new) { if item . has_name (EXCEPT) { let value = expect_associated_value (self . tcx , & item) ; return self . resolve_labels (& item , value) ; } } Labels :: default () } # [doc = " Return all DepNode labels that should be asserted for this item."] # [doc = " index=0 is the \"name\" used for error messages"] fn auto_labels (& mut self , item_id : LocalDefId , attr : & Attribute) -> (& 'static str , Labels) { let node = self . tcx . hir_node_by_def_id (item_id) ; let (name , labels) = match node { HirNode :: Item (item) => { match item . kind { HirItem :: Static (..) => ("ItemStatic" , LABELS_CONST) , HirItem :: Const (..) => ("ItemConst" , LABELS_CONST) , HirItem :: Fn { .. } => ("ItemFn" , LABELS_FN) , HirItem :: Mod (..) => ("ItemMod" , LABELS_HIR_ONLY) , HirItem :: ForeignMod { .. } => ("ItemForeignMod" , LABELS_HIR_ONLY) , HirItem :: GlobalAsm { .. } => ("ItemGlobalAsm" , LABELS_HIR_ONLY) , HirItem :: TyAlias (..) => ("ItemTy" , LABELS_HIR_ONLY) , HirItem :: Enum (..) => ("ItemEnum" , LABELS_ADT) , HirItem :: Struct (..) => ("ItemStruct" , LABELS_ADT) , HirItem :: Union (..) => ("ItemUnion" , LABELS_ADT) , HirItem :: Trait (..) => ("ItemTrait" , LABELS_TRAIT) , HirItem :: Impl { .. } => ("ItemKind::Impl" , LABELS_IMPL) , _ => self . tcx . dcx () . emit_fatal (errors :: UndefinedCleanDirtyItem { span : attr . span () , kind : format ! ("{:?}" , item . kind) , }) , } } HirNode :: TraitItem (item) => match item . kind { TraitItemKind :: Fn (..) => ("Node::TraitItem" , LABELS_FN_IN_TRAIT) , TraitItemKind :: Const (..) => ("NodeTraitConst" , LABELS_CONST_IN_TRAIT) , TraitItemKind :: Type (..) => ("NodeTraitType" , LABELS_CONST_IN_TRAIT) , } , HirNode :: ImplItem (item) => match item . kind { ImplItemKind :: Fn (..) => ("Node::ImplItem" , LABELS_FN_IN_IMPL) , ImplItemKind :: Const (..) => ("NodeImplConst" , LABELS_CONST_IN_IMPL) , ImplItemKind :: Type (..) => ("NodeImplType" , LABELS_CONST_IN_IMPL) , } , _ => self . tcx . dcx () . emit_fatal (errors :: UndefinedCleanDirty { span : attr . span () , kind : format ! ("{node:?}") , }) , } ; let labels = Labels :: from_iter (labels . iter () . flat_map (| s | s . iter () . map (| l | (* l) . to_string ()))) ; (name , labels) } fn resolve_labels (& self , item : & MetaItemInner , value : Symbol) -> Labels { let mut out = Labels :: default () ; for label in value . as_str () . split (',') { let label = label . trim () ; if DepNode :: has_label_string (label) { if out . contains (label) { self . tcx . dcx () . emit_fatal (errors :: RepeatedDepNodeLabel { span : item . span () , label }) ; } out . insert (label . to_string ()) ; } else { self . tcx . dcx () . emit_fatal (errors :: UnrecognizedDepNodeLabel { span : item . span () , label }) ; } } out } fn dep_node_str (& self , dep_node : & DepNode) -> String { if let Some (def_id) = dep_node . extract_def_id (self . tcx) { format ! ("{:?}({})" , dep_node . kind , self . tcx . def_path_str (def_id)) } else { format ! ("{:?}({:?})" , dep_node . kind , dep_node . hash) } } fn assert_dirty (& self , item_span : Span , dep_node : DepNode) { debug ! ("assert_dirty({:?})" , dep_node) ; if self . tcx . dep_graph . is_green (& dep_node) { let dep_node_str = self . dep_node_str (& dep_node) ; self . tcx . dcx () . emit_err (errors :: NotDirty { span : item_span , dep_node_str : & dep_node_str }) ; } } fn assert_clean (& self , item_span : Span , dep_node : DepNode) { debug ! ("assert_clean({:?})" , dep_node) ; if self . tcx . dep_graph . is_red (& dep_node) { let dep_node_str = self . dep_node_str (& dep_node) ; self . tcx . dcx () . emit_err (errors :: NotClean { span : item_span , dep_node_str : & dep_node_str }) ; } } fn assert_loaded_from_disk (& self , item_span : Span , dep_node : DepNode) { debug ! ("assert_loaded_from_disk({:?})" , dep_node) ; if ! self . tcx . dep_graph . debug_was_loaded_from_disk (dep_node) { let dep_node_str = self . dep_node_str (& dep_node) ; self . tcx . dcx () . emit_err (errors :: NotLoaded { span : item_span , dep_node_str : & dep_node_str }) ; } } fn check_item (& mut self , item_id : LocalDefId) { let item_span = self . tcx . def_span (item_id . to_def_id ()) ; let def_path_hash = self . tcx . def_path_hash (item_id . to_def_id ()) ; for attr in self . tcx . get_attrs (item_id , sym :: rustc_clean) { let Some (assertion) = self . assertion_maybe (item_id , attr) else { continue ; } ; self . checked_attrs . insert (attr . id ()) ; for label in assertion . clean . items () . into_sorted_stable_ord () { let dep_node = DepNode :: from_label_string (self . tcx , label , def_path_hash) . unwrap () ; self . assert_clean (item_span , dep_node) ; } for label in assertion . dirty . items () . into_sorted_stable_ord () { let dep_node = DepNode :: from_label_string (self . tcx , label , def_path_hash) . unwrap () ; self . assert_dirty (item_span , dep_node) ; } for label in assertion . loaded_from_disk . items () . into_sorted_stable_ord () { let dep_node = DepNode :: from_label_string (self . tcx , label , def_path_hash) . unwrap () ; self . assert_loaded_from_disk (item_span , dep_node) ; } } } }}}

macro_rules! check_config_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function check_config in module {}", module_path!());
    };
}

mkfn!{
    check_config_introspect!();
    # [doc = " Given a `#[rustc_clean]` attribute, scan for a `cfg=\"foo\"` attribute and check whether we have"] # [doc = " a cfg flag called `foo`."] fn check_config (tcx : TyCtxt < '_ > , attr : & Attribute) -> bool { debug ! ("check_config(attr={:?})" , attr) ; let config = & tcx . sess . psess . config ; debug ! ("check_config: config={:?}" , config) ; let mut cfg = None ; for item in attr . meta_item_list () . unwrap_or_else (ThinVec :: new) { if item . has_name (CFG) { let value = expect_associated_value (tcx , & item) ; debug ! ("check_config: searching for cfg {:?}" , value) ; cfg = Some (config . contains (& (value , None))) ; } else if ! (item . has_name (EXCEPT) || item . has_name (LOADED_FROM_DISK)) { tcx . dcx () . emit_err (errors :: UnknownRustcCleanArgument { span : item . span () }) ; } } match cfg { None => tcx . dcx () . emit_fatal (errors :: NoCfg { span : attr . span () }) , Some (c) => c , } }
}

macro_rules! expect_associated_value_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function expect_associated_value in module {}", module_path!());
    };
}

mkfn!{
    expect_associated_value_introspect!();
    fn expect_associated_value (tcx : TyCtxt < '_ > , item : & MetaItemInner) -> Symbol { if let Some (value) = item . value_str () { value } else if let Some (ident) = item . ident () { tcx . dcx () . emit_fatal (errors :: AssociatedValueExpectedFor { span : item . span () , ident }) ; } else { tcx . dcx () . emit_fatal (errors :: AssociatedValueExpected { span : item . span () }) ; } }
}
mkitem!{mkstruct!{# [doc = " A visitor that collects all `#[rustc_clean]` attributes from"] # [doc = " the HIR. It is used to verify that we really ran checks for all annotated"] # [doc = " nodes."] struct FindAllAttrs < 'tcx > { tcx : TyCtxt < 'tcx > , found_attrs : Vec < & 'tcx Attribute > , }}}
mkitem!{mkimpl!{impl < 'tcx > FindAllAttrs < 'tcx > { fn is_active_attr (& mut self , attr : & Attribute) -> bool { if attr . has_name (sym :: rustc_clean) && check_config (self . tcx , attr) { return true ; } false } fn report_unchecked_attrs (& self , mut checked_attrs : FxHashSet < ast :: AttrId >) { for attr in & self . found_attrs { if ! checked_attrs . contains (& attr . id ()) { self . tcx . dcx () . emit_err (errors :: UncheckedClean { span : attr . span () }) ; checked_attrs . insert (attr . id ()) ; } } } }}}
mkitem!{mkimpl!{impl < 'tcx > intravisit :: Visitor < 'tcx > for FindAllAttrs < 'tcx > { type NestedFilter = nested_filter :: All ; fn maybe_tcx (& mut self) -> Self :: MaybeTyCtxt { self . tcx } fn visit_attribute (& mut self , attr : & 'tcx Attribute) { if self . is_active_attr (attr) { self . found_attrs . push (attr) ; } } }}}